import {loadBugModel} from './ai-loader.js';
import{motion,cropBounds,strongEvidence,sameTarget}from'./detector.js';
const $=id=>document.getElementById(id),video=$('video'),photo=$('photo'),overlay=$('overlay'),ctx=overlay.getContext('2d'),work=document.createElement('canvas');work.width=160;work.height=120;const wc=work.getContext('2d',{willReadFrequently:true});
let stream,model,loading=false,busy=false,paused=false,isPhoto=false,facing='environment',previous=null,target=null,generation=0,nextId=0,lastCheck=0,torch=false,cameraRequest=0;
const labels=['a close-up photograph of a real insect or spider','a piece of lint, dust, dirt, or debris','a shadow or reflection','a textured carpet, wood, wall, or floor','a screw, hole, hardware, or household object','a leaf, seed, or plant fragment','a stain, crack, or printed pattern'];
function message(s){$('message').textContent=s;}function result(title,detail){$('result').textContent=title;$('detail').textContent=detail;}
function reset(){generation++;target=null;previous=null;ctx.clearRect(0,0,overlay.width,overlay.height);}
function source(){return isPhoto?photo:video;}function size(){return isPhoto?[photo.width,photo.height]:[video.videoWidth,video.videoHeight];}
function draw(d){const box=$('viewer').getBoundingClientRect(),ratio=devicePixelRatio||1;overlay.width=Math.round(box.width*ratio);overlay.height=Math.round(box.height*ratio);ctx.setTransform(ratio,0,0,ratio,0,0);if(!d?.confirmed)return;const[w,h]=size(),scale=Math.min(box.width/w,box.height/h),ox=(box.width-w*scale)/2,oy=(box.height-h*scale)/2,x=ox+d.minX/160*w*scale,y=oy+d.minY/120*h*scale,bw=(d.maxX-d.minX+1)/160*w*scale,bh=(d.maxY-d.minY+1)/120*h*scale;ctx.strokeStyle='#ff4b45';ctx.lineWidth=3;ctx.strokeRect(x-8,y-8,bw+16,bh+16);ctx.font='bold 12px Arial';ctx.fillStyle='#ff4b45';ctx.fillText('LIKELY BUG',Math.max(8,x-8),Math.max(55,y-17));}
async function load(){
  if(model||loading)return;
  loading=true;$('loadAI').disabled=true;$('aiStatus').textContent='Preparing…';message('Loading the AI components. Keep this page open.');
  try{
    model=await loadBugModel(labels,p=>{
      if(p.status==='progress'&&Number.isFinite(p.progress)){
        const component=p.file?.includes('text_model')?'Language model':p.file?.includes('vision_model')?'Vision model':'AI files';
        $('aiStatus').textContent=Math.round(p.progress)+'%';message(component+' downloading: '+Math.round(p.progress)+'%. Keep this page open.');
      }else if(p.status==='done'){$('aiStatus').textContent='Preparing…';message('Download complete for one component. Preparing the AI…');}
    });
    $('aiStatus').textContent='Ready';$('loadAI').textContent='AI ready';message('Vision model ready. Red requires two strong checks.');if(isPhoto)inspect();
  }catch(e){
    console.error('Bug Finder AI initialization failed',e);
    $('aiStatus').textContent='Unavailable';$('loadAI').textContent='Retry AI download';$('loadAI').disabled=false;
    const reason=String(e?.message||e).slice(0,260);
    message('AI could not start: '+reason+'. Check your connection and retry. If it repeats, reload this page. Red outlines stay off.');
  }finally{loading=false;}
}
function stop(){cameraRequest++;if(stream)stream.getTracks().forEach(t=>t.stop());stream=null;reset();}
async function camera(){stop();const request=cameraRequest;isPhoto=false;photo.hidden=true;video.hidden=false;paused=false;$('pause').textContent='Pause';try{if(!navigator.mediaDevices?.getUserMedia)throw Error('Camera access needs Safari over HTTPS.');const opened=await navigator.mediaDevices.getUserMedia({video:{facingMode:{ideal:facing},width:{ideal:1280},height:{ideal:960}},audio:false});if(request!==cameraRequest){opened.getTracks().forEach(t=>t.stop());return;}stream=opened;video.srcObject=stream;await video.play();$('welcome').hidden=true;$('welcome').style.display='none';$('cameraStatus').textContent='LIVE';$('dimensions').textContent='LIVE SCANNER';for(const id of['pause','flip','save','inspect'])$(id).disabled=false;const caps=stream.getVideoTracks()[0].getCapabilities?.()||{};$('torch').disabled=!caps.torch;torch=false;$('torch').textContent='Light';message('');result('Looking quietly.','Small moving targets are checked in the background. Keep the camera steady.');load();}catch(e){$('cameraStatus').textContent='CAMERA OFF';$('welcome').style.display='flex';for(const id of['pause','flip','save','inspect','torch'])$(id).disabled=true;message(e.name==='NotAllowedError'?'Camera permission was denied. Allow camera access in Safari settings, then try again.':e.message);}}
async function verify(d,manual=false){if(!model||busy)return;busy=true;lastCheck=Date.now();const token=generation,id=d.id;try{const[w,h]=size(),region=d.hits?{...d,minX:d.minX-4,minY:d.minY-4,maxX:d.maxX+4,maxY:d.maxY+4}:d,crop=cropBounds(region,w,h),c=document.createElement('canvas');c.width=c.height=224;const cc=c.getContext('2d');cc.drawImage(source(),crop.x,crop.y,crop.size,crop.size,0,0,224,224);const scores=await model(c.toDataURL('image/jpeg',.92),labels);if(token!==generation||target?.id!==id)return;d.hits=strongEvidence(scores)?d.hits+1:0;d.confirmed=d.hits>=2;d.verifiedAt=Date.now();if(d.confirmed)result('Likely bug.','Two strong AI checks agree on this target. Look closely to confirm; this is not a species identification.');else if(manual)result(d.hits?'One check agrees.':'No strong match.',d.hits?'Checking again before showing red.':'The model did not find enough evidence. Try a closer, sharper view.');draw(d);}catch(e){if(token===generation){d.hits=0;d.confirmed=false;draw(null);message('This AI check failed. Try again; no result has been confirmed.');}}finally{busy=false;}if(manual&&token===generation&&target?.id===id&&d.hits===1){await new Promise(r=>setTimeout(r,700));if(token===generation&&target?.id===id)await verify(d,true);}}
function scan(){if(paused||isPhoto||!stream||video.readyState<2)return;wc.drawImage(video,0,0,160,120);const pixels=wc.getImageData(0,0,160,120).data,g=new Uint8Array(19200);for(let i=0;i<g.length;i++)g[i]=pixels[i*4]*.299+pixels[i*4+1]*.587+pixels[i*4+2]*.114;const m=motion(g,previous);previous=g;if(m.shake){reset();$('scene').textContent='Hold steady — camera movement';result('Hold steady.','The scene is moving too much for a reliable check.');return;}$('scene').textContent=model?'Scanning · AI ready':'Scanning · waiting for AI';const match=target&&m.candidates.find(c=>sameTarget(c,target));const candidate=match||m.candidates[0];if(!candidate){if(target&&Date.now()-target.seen>600){reset();result('Looking quietly.','No target is currently verified. Keep the camera steady.');}return;}if(!match){generation++;target={...candidate,id:++nextId,hits:0,streak:1,seen:Date.now(),confirmed:false};draw(null);}else{Object.assign(target,candidate);target.streak++;target.seen=Date.now();}if(target.confirmed&&Date.now()-target.verifiedAt>2500){target.confirmed=false;target.hits=0;}draw(target);if(target.streak>=4&&Date.now()-lastCheck>900)verify(target);}
function inspect(){if(!model){message('Load the vision model before checking a photo or the center.');load();return;}if(busy){message('A check is still finishing. Try again in a moment.');return;}reset();target={minX:55,minY:35,maxX:105,maxY:85,id:++nextId,hits:0,confirmed:false,seen:Date.now()};if(!isPhoto){paused=true;$('pause').textContent='Resume';video.pause();$('cameraStatus').textContent='PAUSED';}result('Checking the center.','Keep the bug large and clear in the center. Two strong model checks are required.');verify(target,true);}
$('start').onclick=camera;$('loadAI').onclick=load;$('inspect').onclick=inspect;$('flip').onclick=()=>{facing=facing==='environment'?'user':'environment';camera();};$('pause').onclick=()=>{paused=!paused;reset();$('pause').textContent=paused?'Resume':'Pause';$('cameraStatus').textContent=paused?'PAUSED':'LIVE';if(paused)video.pause();else video.play().catch(()=>message('Tap Start camera to reconnect.'));result(paused?'Scan paused.':'Looking quietly.',paused?'Resume to continue checking for moving targets.':'Hold your camera steady.');};$('torch').onclick=async()=>{try{await stream.getVideoTracks()[0].applyConstraints({advanced:[{torch:!torch}]});torch=!torch;$('torch').textContent=torch?'Light off':'Light';}catch{message('This camera does not support its light here.');}};
$('upload').onchange=async e=>{const file=e.target.files[0];if(!file)return;if(file.size>25*1024*1024){message('Choose a photo smaller than 25 MB.');return;}const url=URL.createObjectURL(file),img=new Image();try{await new Promise((resolve,reject)=>{img.onload=resolve;img.onerror=reject;img.src=url;});stop();isPhoto=true;video.hidden=true;photo.hidden=false;const s=Math.min(1,2048/Math.max(img.naturalWidth,img.naturalHeight));photo.width=Math.round(img.naturalWidth*s);photo.height=Math.round(img.naturalHeight*s);photo.getContext('2d').drawImage(img,0,0,photo.width,photo.height);$('welcome').style.display='none';$('cameraStatus').textContent='PHOTO';$('dimensions').textContent='CENTER INSPECTION';$('scene').textContent='Photo stays on this device';$('pause').disabled=true;$('torch').disabled=true;$('flip').disabled=false;$('save').disabled=false;$('inspect').disabled=false;result('Photo ready.','The center of your photo will be checked. A wide photo may miss tiny bugs.');inspect();}catch{message('That image could not be opened. Try JPEG or PNG.');}finally{URL.revokeObjectURL(url);e.target.value='';}};
$('save').onclick=()=>{const[w,h]=size();if(!w)return;const c=document.createElement('canvas');c.width=w;c.height=h;c.getContext('2d').drawImage(source(),0,0,w,h);c.toBlob(blob=>{if(!blob)return;const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='bug-finder-'+Date.now()+'.jpg';a.click();setTimeout(()=>URL.revokeObjectURL(url),10000);message('Photo opened for saving. On iPhone, use Share → Save Image if needed.');},'image/jpeg',.94);};
setInterval(scan,160);addEventListener('resize',()=>draw(target));addEventListener('pagehide',stop);document.addEventListener('visibilitychange',()=>{if(document.hidden&&!isPhoto){stop();$('cameraStatus').textContent='CAMERA OFF';$('welcome').style.display='flex';for(const id of['pause','flip','torch','inspect','save'])$(id).disabled=true;}});
if('serviceWorker'in navigator)navigator.serviceWorker.register('./sw.js').catch(()=>{});
